import glob

files = sorted(glob.glob('/inputs/*-*.md'))
files = [f.split('/')[-1] for f in files]

def get_title(path):
    text = open(path, 'r', encoding='utf-8').read()
    for line in text.splitlines():
        if line.startswith('# '):
            return line[2:].strip()
    for line in text.splitlines():
        if line.strip() == '#':
            return ''
    raise ValueError("no heading found in "+path)

titles = {f: get_title('/inputs/'+f) for f in files}

orig = open('/inputs/README.md', 'rb').read()

header = "| File | Type | Description |\n| --- | --- | --- |\n"
rows = ""
for f in files:
    title = titles[f]
    rows += f"| [{f}](../inputs/{f}) | .md | {title} |\n"

appended = "\n## Reference index\n\n" + header + rows

new_content_bytes = orig + appended.encode('utf-8')

with open('/work/README.md', 'wb') as out:
    out.write(new_content_bytes)

print(repr(new_content_bytes[-700:]))
